import React, { useRef, useState, useEffect } from 'react'

function GraphicsDemoPage() {
  const canvasRef = useRef(null)
  const [shapeType, setShapeType] = useState('rect')
  const [color, setColor] = useState('#667eea')
  const [opacity, setOpacity] = useState(100)
  const [rotation, setRotation] = useState(0)
  const [scale, setScale] = useState(100)
  const [blendMode, setBlendMode] = useState('source-over')
  const [animating, setAnimating] = useState(false)
  const animationRef = useRef(null)

  useEffect(() => {
    // Draw initial shape
    if (canvasRef.current) {
      drawShape()
    }
  }, [])

  useEffect(() => {
    if (animating) {
      animate()
    } else {
      if (animationRef.current) {
        clearTimeout(animationRef.current)
      }
    }

    return () => {
      if (animationRef.current) {
        clearTimeout(animationRef.current)
      }
    }
  }, [animating])

  const hexToRgba = (hex, alpha) => {
    const r = parseInt(hex.slice(1, 3), 16)
    const g = parseInt(hex.slice(3, 5), 16)
    const b = parseInt(hex.slice(5, 7), 16)
    return `rgba(${r}, ${g}, ${b}, ${alpha})`
  }

  const drawShape = () => {
    const canvas = canvasRef.current
    if (!canvas) return

    const ctx = canvas.getContext('2d')
    const x = Math.random() * (canvas.width - 200) + 100
    const y = Math.random() * (canvas.height - 200) + 100
    const size = 50

    const fillColor = hexToRgba(color, opacity / 100)
    const rotationRad = (rotation * Math.PI) / 180
    const scaleValue = scale / 100

    ctx.save()
    ctx.globalCompositeOperation = blendMode
    ctx.translate(x, y)
    ctx.rotate(rotationRad)
    ctx.scale(scaleValue, scaleValue)

    ctx.fillStyle = fillColor
    ctx.strokeStyle = fillColor
    ctx.lineWidth = 3

    switch(shapeType) {
      case 'rect':
        ctx.fillRect(-size/2, -size/2, size, size)
        break
      case 'circle':
        ctx.beginPath()
        ctx.arc(0, 0, size/2, 0, Math.PI * 2)
        ctx.fill()
        break
      case 'triangle':
        ctx.beginPath()
        ctx.moveTo(0, -size/2)
        ctx.lineTo(size/2, size/2)
        ctx.lineTo(-size/2, size/2)
        ctx.closePath()
        ctx.fill()
        break
      case 'line':
        ctx.beginPath()
        ctx.moveTo(-size/2, -size/2)
        ctx.lineTo(size/2, size/2)
        ctx.stroke()
        break
      case 'polygon':
        const sides = 6
        ctx.beginPath()
        for (let i = 0; i < sides; i++) {
          const angle = (i * 2 * Math.PI) / sides
          const px = (size/2) * Math.cos(angle)
          const py = (size/2) * Math.sin(angle)
          if (i === 0) ctx.moveTo(px, py)
          else ctx.lineTo(px, py)
        }
        ctx.closePath()
        ctx.fill()
        break
    }

    ctx.restore()
  }

  const clearCanvas = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    ctx.clearRect(0, 0, canvas.width, canvas.height)
  }

  const animate = () => {
    setRotation(prev => (prev + 5) % 360)
    drawShape()

    animationRef.current = setTimeout(() => {
      requestAnimationFrame(() => animate())
    }, 100)
  }

  const toggleAnimation = () => {
    setAnimating(!animating)
  }

  return (
    <>
      <style>{`
        body {
          background: linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%);
          min-height: 100vh;
          padding: 2rem;
        }

        .graphics-demo-page {
          max-width: 1200px;
          margin: 0 auto;
          background: white;
          border-radius: 12px;
          box-shadow: 0 20px 60px rgba(0,0,0,0.3);
          overflow: hidden;
        }

        .demo-header {
          background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
          color: white;
          padding: 2rem;
          text-align: center;
        }

        .demo-header h1 {
          margin-bottom: 0.5rem;
        }

        .demo-content {
          display: grid;
          grid-template-columns: 300px 1fr;
          gap: 2rem;
          padding: 2rem;
        }

        .demo-controls {
          background: #f8f9fa;
          padding: 1.5rem;
          border-radius: 8px;
        }

        .control-group {
          margin-bottom: 1.5rem;
        }

        .control-group label {
          display: block;
          font-weight: 600;
          margin-bottom: 0.5rem;
          color: #2c3e50;
        }

        .control-group select,
        .control-group input[type="color"],
        .control-group input[type="range"] {
          width: 100%;
          padding: 0.5rem;
          border: 1px solid #ddd;
          border-radius: 4px;
          font-size: 1rem;
        }

        .control-group input[type="range"] {
          padding: 0;
        }

        .value-display {
          float: right;
          color: #2E7D32;
          font-weight: 600;
        }

        .demo-button {
          width: 100%;
          padding: 0.75rem;
          background: #2E7D32;
          color: white;
          border: none;
          border-radius: 4px;
          font-size: 1rem;
          font-weight: 600;
          cursor: pointer;
          transition: background 0.3s;
          margin-bottom: 0.5rem;
        }

        .demo-button:hover {
          background: #1B5E20;
        }

        .demo-button.secondary {
          background: #e74c3c;
        }

        .demo-button.secondary:hover {
          background: #c0392b;
        }

        .demo-button.animating {
          background: #e74c3c;
        }

        .canvas-container {
          background: #f0f0f0;
          border-radius: 8px;
          padding: 1rem;
          display: flex;
          justify-content: center;
          align-items: center;
        }

        #demo-canvas {
          background: white;
          border: 2px solid #ddd;
          cursor: crosshair;
          box-shadow: 0 4px 6px rgba(0,0,0,0.1);
        }

        .info {
          background: #e8f4f8;
          padding: 1rem;
          border-radius: 4px;
          margin-bottom: 1rem;
          font-size: 0.9rem;
          line-height: 1.6;
        }

        @media (max-width: 900px) {
          .demo-content {
            grid-template-columns: 1fr;
          }
        }
      `}</style>

      <div className="graphics-demo-page">
        <header className="demo-header">
          <h1>2D Graphics Engine Demo</h1>
          <p>Interactive demonstration with shape rendering, transformations, and blend modes</p>
        </header>

        <div className="demo-content">
          <div className="demo-controls">
            <div className="info">
              This demo showcases JavaScript Canvas API capabilities. Use the controls to draw shapes and apply transformations. Click the canvas to draw!
            </div>

            <div className="control-group">
              <label>Shape Type</label>
              <select value={shapeType} onChange={(e) => setShapeType(e.target.value)}>
                <option value="rect">Rectangle</option>
                <option value="circle">Circle</option>
                <option value="triangle">Triangle</option>
                <option value="line">Line</option>
                <option value="polygon">Hexagon</option>
              </select>
            </div>

            <div className="control-group">
              <label>Color</label>
              <input
                type="color"
                value={color}
                onChange={(e) => setColor(e.target.value)}
              />
            </div>

            <div className="control-group">
              <label>
                Opacity
                <span className="value-display">{opacity}%</span>
              </label>
              <input
                type="range"
                min="0"
                max="100"
                value={opacity}
                onChange={(e) => setOpacity(parseInt(e.target.value))}
              />
            </div>

            <div className="control-group">
              <label>
                Rotation
                <span className="value-display">{rotation}°</span>
              </label>
              <input
                type="range"
                min="0"
                max="360"
                value={rotation}
                onChange={(e) => setRotation(parseInt(e.target.value))}
              />
            </div>

            <div className="control-group">
              <label>
                Scale
                <span className="value-display">{(scale / 100).toFixed(1)}x</span>
              </label>
              <input
                type="range"
                min="10"
                max="200"
                value={scale}
                onChange={(e) => setScale(parseInt(e.target.value))}
              />
            </div>

            <div className="control-group">
              <label>Blend Mode</label>
              <select value={blendMode} onChange={(e) => setBlendMode(e.target.value)}>
                <option value="source-over">Normal</option>
                <option value="multiply">Multiply</option>
                <option value="screen">Screen</option>
                <option value="overlay">Overlay</option>
                <option value="difference">Difference</option>
              </select>
            </div>

            <button className="demo-button" onClick={drawShape}>
              Draw Shape
            </button>
            <button className="demo-button secondary" onClick={clearCanvas}>
              Clear Canvas
            </button>
            <button
              className={`demo-button ${animating ? 'animating' : ''}`}
              onClick={toggleAnimation}
            >
              {animating ? 'Stop Animation' : 'Animate Shapes'}
            </button>
          </div>

          <div className="canvas-container">
            <canvas
              ref={canvasRef}
              id="demo-canvas"
              width="700"
              height="600"
              onClick={drawShape}
            />
          </div>
        </div>
      </div>
    </>
  )
}

export default GraphicsDemoPage

