/**
 * Site Navigation Styles
 * Responsive navigation bar with accessible hamburger menu
 */

/* Desktop Navigation Bar */
.site-nav {
  width: 100%;
  background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
  padding: var(--space-sm) var(--space-lg);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.site-nav .nav-brand {
  color: white;
  font-weight: 600;
  text-decoration: none;
  font-size: 1.125rem;
}

.site-nav .nav-brand:hover {
  opacity: 0.9;
}

.site-nav .nav-links {
  display: flex;
  gap: var(--space-md);
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-nav .nav-links a {
  color: rgba(255, 255, 255, 0.9);
  text-decoration: none;
  padding: var(--space-xs) var(--space-sm);
  border-radius: 4px;
  transition: background var(--timing-instant) var(--easing-standard);
}

.site-nav .nav-links a:hover {
  background: rgba(255, 255, 255, 0.15);
}

.site-nav .nav-links a:focus-visible {
  outline: 2px solid white;
  outline-offset: 2px;
}

.site-nav .nav-links a.active {
  background: rgba(255, 255, 255, 0.2);
  font-weight: 600;
  position: relative;
}

.site-nav .nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: var(--space-sm);
  right: var(--space-sm);
  height: 2px;
  background: white;
}

/* Hamburger Menu Button (hidden on desktop) */
.menu-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  color: white;
  padding: var(--space-xs);
  position: relative;
  width: 32px;
  height: 32px;
  z-index: 101;
}

.menu-toggle:hover {
  opacity: 0.9;
}

.menu-toggle:focus-visible {
  outline: 2px solid white;
  outline-offset: 2px;
  border-radius: 4px;
}

/* CSS Hamburger Icon (3 bars) */
.hamburger-icon,
.hamburger-icon::before,
.hamburger-icon::after {
  display: block;
  width: 24px;
  height: 2px;
  background: white;
  position: absolute;

