/**
 * Global styles matching original HTML pages
 */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  line-height: 1.6;
  color: #333;
  background: #f5f5f5;
}

/* Page-specific body backgrounds set by route */
body.cpu-simulator-page,
body.graphics-demo-page,
body.wasm-demo-page {
  background: linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%);
  min-height: 100vh;
  padding: 2rem;
}

/* Container for demo pages */
.container {
  max-width: 1400px;
  margin: 0 auto;
  background: white;
  border-radius: 12px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.3);
  overflow: hidden;
}

/* Header inside container */
.container header {
  background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
  color: white;
  padding: 2rem;
  text-align: center;
}

.container header h1 {
  margin-bottom: 0.5rem;
}

.container header p {
  opacity: 0.9;
  font-size: 1.1rem;
}

/* Demo layout (sidebar + main area) */
.demo-layout {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 2rem;
  padding: 2rem;
}

