   282→    <script>
   283→        const canvas = document.getElementById('canvas');
   284→        const ctx = canvas.getContext('2d');
   285→
   286→        // Control elements
   287→        const shapeType = document.getElementById('shapeType');
   288→        const colorPicker = document.getElementById('colorPicker');
   289→        const opacitySlider = document.getElementById('opacity');
   290→        const rotationSlider = document.getElementById('rotation');
   291→        const scaleSlider = document.getElementById('scale');
   292→        const blendMode = document.getElementById('blendMode');
   293→        const drawBtn = document.getElementById('drawBtn');
   294→        const clearBtn = document.getElementById('clearBtn');
   295→        const animateBtn = document.getElementById('animateBtn');
   296→
   297→        // Value displays
   298→        const opacityValue = document.getElementById('opacityValue');
   299→        const rotationValue = document.getElementById('rotationValue');
   300→        const scaleValue = document.getElementById('scaleValue');
   301→
   302→        // Update value displays
   303→        opacitySlider.addEventListener('input', (e) => {
   304→            opacityValue.textContent = e.target.value + '%';
   305→        });
   306→
   307→        rotationSlider.addEventListener('input', (e) => {
   308→            rotationValue.textContent = e.target.value + '°';
   309→        });
   310→
   311→        scaleSlider.addEventListener('input', (e) => {
   312→            scaleValue.textContent = (e.target.value / 100).toFixed(1) + 'x';
   313→        });
   314→
   315→        // Helper function to convert hex to rgba
   316→        function hexToRgba(hex, alpha) {
   317→            const r = parseInt(hex.slice(1, 3), 16);
   318→            const g = parseInt(hex.slice(3, 5), 16);
   319→            const b = parseInt(hex.slice(5, 7), 16);
   320→            return `rgba(${r}, ${g}, ${b}, ${alpha})`;
   321→        }
   322→
   323→        // Draw shape function
   324→        function drawShape() {
   325→            const x = Math.random() * (canvas.width - 200) + 100;
   326→            const y = Math.random() * (canvas.height - 200) + 100;
   327→            const size = 50;
   328→
   329→            const color = hexToRgba(colorPicker.value, opacitySlider.value / 100);
   330→            const rotation = (rotationSlider.value * Math.PI) / 180;
   331→            const scale = scaleSlider.value / 100;
   332→
   333→            ctx.save();
   334→            ctx.globalCompositeOperation = blendMode.value;
   335→            ctx.translate(x, y);
   336→            ctx.rotate(rotation);
   337→            ctx.scale(scale, scale);
   338→
   339→            ctx.fillStyle = color;
   340→            ctx.strokeStyle = color;
   341→            ctx.lineWidth = 3;
   342→
   343→            switch(shapeType.value) {
   344→                case 'rect':
   345→                    ctx.fillRect(-size/2, -size/2, size, size);
   346→                    break;
   347→                case 'circle':
   348→                    ctx.beginPath();
   349→                    ctx.arc(0, 0, size/2, 0, Math.PI * 2);
   350→                    ctx.fill();
   351→                    break;
   352→                case 'triangle':
   353→                    ctx.beginPath();
   354→                    ctx.moveTo(0, -size/2);
   355→                    ctx.lineTo(size/2, size/2);
   356→                    ctx.lineTo(-size/2, size/2);
   357→                    ctx.closePath();
   358→                    ctx.fill();
   359→                    break;
   360→                case 'line':
   361→                    ctx.beginPath();
   362→                    ctx.moveTo(-size/2, -size/2);
   363→                    ctx.lineTo(size/2, size/2);
   364→                    ctx.stroke();
   365→                    break;
   366→                case 'polygon':
   367→                    const sides = 6;
   368→                    ctx.beginPath();
   369→                    for (let i = 0; i < sides; i++) {
   370→                        const angle = (i * 2 * Math.PI) / sides;
   371→                        const px = (size/2) * Math.cos(angle);
   372→                        const py = (size/2) * Math.sin(angle);
   373→                        if (i === 0) ctx.moveTo(px, py);
   374→                        else ctx.lineTo(px, py);
   375→                    }
   376→                    ctx.closePath();
   377→                    ctx.fill();
   378→                    break;
   379→            }
   380→
   381→            ctx.restore();
   382→        }
   383→
   384→        // Clear canvas
   385→        function clearCanvas() {
   386→            ctx.clearRect(0, 0, canvas.width, canvas.height);
   387→        }
   388→
   389→        // Animation
   390→        let animating = false;
   391→        let animationId;
   392→
   393→        function animate() {
   394→            if (!animating) return;
   395→
   396→            // Randomize some values for interesting animations
   397→            rotationSlider.value = (parseInt(rotationSlider.value) + 5) % 360;
   398→            rotationValue.textContent = rotationSlider.value + '°';
   399→
   400→            drawShape();
   401→
   402→            animationId = setTimeout(() => {
   403→                requestAnimationFrame(animate);
   404→            }, 100);
   405→        }
   406→
   407→        function toggleAnimation() {
   408→            animating = !animating;
   409→            if (animating) {
   410→                animateBtn.textContent = 'Stop Animation';
   411→                animateBtn.style.background = '#e74c3c';
   412→                animate();
   413→            } else {
   414→                animateBtn.textContent = 'Animate Shapes';
   415→                animateBtn.style.background = '#2E7D32';
   416→                clearTimeout(animationId);
   417→            }
   418→        }
   419→
   420→        // Event listeners
   421→        drawBtn.addEventListener('click', drawShape);
   422→        clearBtn.addEventListener('click', clearCanvas);
   423→        animateBtn.addEventListener('click', toggleAnimation);
   424→
   425→        // Canvas click to draw
   426→        canvas.addEventListener('click', drawShape);
   427→
   428→        // Draw initial shape
   429→        drawShape();
   430→    </script>
