            <summary style={{ background: 'linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%)', color: 'white', padding: '1.5rem', fontSize: '1.25rem', fontWeight: 600, cursor: 'pointer', userSelect: 'none' }}>
