import React, { useEffect, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import Breadcrumbs from '../components/shared/Breadcrumbs'

function GraphicsWasmPage() {
  const canvasRef = useRef(null)
  const wasmCanvasRef = useRef(null)
  const moduleRef = useRef(null)
  const [status, setStatus] = useState({ type: 'loading', message: 'Loading WebAssembly module...' })
  const [currentDemo, setCurrentDemo] = useState('shapes')
  const [currentParams, setCurrentParams] = useState({})
  const [controlsDisabled, setControlsDisabled] = useState(true)
  const [demoDescription, setDemoDescription] = useState({
    title: 'Select a Demo',
    description: 'Choose from the presets below to explore different capabilities of the graphics engine.'
  })

  // Demo descriptions
  const demoInfo = {
    shapes: {
      title: 'Basic Shapes',
      description: 'Demonstrates rectangle and polygon rendering with the C++ canvas API. Uses drawRect() and drawConvexPolygon() functions.'
    },
    transforms: {
      title: 'Transformations',
      description: 'Shows matrix transformations including translate, rotate, and scale operations. Uses save/restore to manage the CTM stack.'
    },
    gradients: {
      title: 'Linear Gradients',
      description: 'Linear gradient shaders with multiple color stops and tile modes. Try Clamp (default), Repeat (tiling), or Mirror (reflecting) to see how gradients extend beyond their endpoints.'
    },
    'blend-modes': {
      title: 'Blend Modes',
      description: 'Porter-Duff compositing operators demonstrating how source and destination pixels combine. Blue circle (destination) drawn first, red circle (source) with blend mode second. Try SrcOver (normal blend), SrcIn (intersection), DstOut (erase), or Xor (exclude overlap).'
    },
    paths: {
      title: 'Curved Paths',
      description: 'GPath API with Bezier curves. Demonstrates moveTo, lineTo, quadTo, and cubicTo path operations for complex shapes.'
    },
    'radial-gradients': {
      title: 'Radial Gradients',
      description: 'Circular gradient shaders radiating from a center point. Demonstrates GCreateRadialGradientShader() with tile modes. Clamp extends the final color, Repeat tiles the gradient outward, Mirror reflects the gradient.'
    },
    'sweep-gradients': {
      title: 'Sweep/Angle Gradients',
      description: 'Conical gradients that rotate around a center point (like a color wheel). The gradient sweeps in a circle, changing colors based on angle from the center. Adjust "Angle Direction" to rotate where the gradient starts. Great for pie charts, loading spinners, and radial UI elements!'
    },
    'bitmap-shader': {
      title: 'Bitmap/Texture Shader',
      description: 'Texture mapping with PNG images. Demonstrates GCreateBitmapShader() with transformation matrices and tile modes. Clamp extends edge pixels, Repeat tiles the texture, Mirror reflects it. Scale and position the texture in real-time!'
    },
    mesh: {
      title: 'Mesh Rendering',
      description: 'Triangle mesh rendering with vertex colors. Uses drawMesh() to render indexed triangle geometry with interpolated colors.'
    },
    'poly-spiral': {
      title: 'Polygon Spiral',
      description: 'Nested polygons with increasing sides creating a mesmerizing kaleidoscope effect. Each polygon has one more side than the inner polygon (triangle→square→pentagon→hexagon...), rotated around a central axis. Demonstrates drawConvexPolygon() with save/restore and translate transformations!'
    }
  }

  // Load WebAssembly module
  useEffect(() => {
    let mounted = true

    function initializeWasm() {
      if (window.GraphicsEngine) {
        window.GraphicsEngine().then((module) => {
          if (mounted) {
            moduleRef.current = module
            const wasmCanvas = new module.CanvasWrapper(800, 600)
            wasmCanvasRef.current = wasmCanvas

            setStatus({ type: 'success', message: '✅ Engine Ready!' })
            setControlsDisabled(false)
            if (canvasRef.current) {
              canvasRef.current.style.display = 'block'
            }

            // Run initial demo
            runDemo('shapes')
          }
        }).catch((error) => {
          if (mounted) {
            setStatus({ type: 'error', message: '❌ Failed to load WebAssembly module' })
            console.error('WASM load error:', error)
          }
        })
      } else {
        // GraphicsEngine not available yet, load the script
        const script = document.createElement('script')
        script.src = '/graphics_engine.js'
        script.async = true

        script.onload = () => {
          if (mounted && window.GraphicsEngine) {
            initializeWasm()
          } else {
            if (mounted) {
              setStatus({ type: 'error', message: '❌ GraphicsEngine not found after script load' })
            }
          }
        }

        script.onerror = () => {
          if (mounted) {
            setStatus({ type: 'error', message: '❌ Failed to load graphics_engine.js' })
          }
        }

        document.body.appendChild(script)
      }
    }

    initializeWasm()

    return () => {
      mounted = false
    }
  }, [])

  // Run demo when selection changes
  useEffect(() => {
    if (wasmCanvasRef.current && !controlsDisabled) {
      runDemo(currentDemo)
    }
  }, [currentDemo, controlsDisabled])

  const updateCanvasDisplay = () => {
    if (!wasmCanvasRef.current || !moduleRef.current || !canvasRef.current) return

    const wasmCanvas = wasmCanvasRef.current
    const Module = moduleRef.current
    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')

    try {
      const width = wasmCanvas.getWidth()
      const height = wasmCanvas.getHeight()
      const pixelPtr = wasmCanvas.getPixelsPtr()
      const pixelCount = width * height

      let wasmPixels
      if (Module.HEAPU32) {
        wasmPixels = new Uint32Array(Module.HEAPU32.buffer, pixelPtr, pixelCount)
      } else if (Module.HEAPU8) {
        wasmPixels = new Uint32Array(Module.HEAPU8.buffer, pixelPtr, pixelCount)
      }

      const imageData = ctx.createImageData(width, height)
      const data = imageData.data

      // Convert premultiplied ARGB to non-premultiplied RGBA
      for (let i = 0; i < pixelCount; i++) {
        const argb = wasmPixels[i]
        const a = (argb >> 24) & 0xFF
        let r = (argb >> 16) & 0xFF
        let g = (argb >> 8) & 0xFF
        let b = argb & 0xFF

        // Unpremultiply RGB by alpha
        if (a > 0 && a < 255) {
          r = Math.round((r * 255) / a)
          g = Math.round((g * 255) / a)
          b = Math.round((b * 255) / a)
        }

        const idx = i * 4
        data[idx] = r
        data[idx + 1] = g
        data[idx + 2] = b
        data[idx + 3] = a
      }

      ctx.putImageData(imageData, 0, 0)
    } catch (e) {
      console.error('Error updating canvas:', e)
    }
  }

  const runDemo = (demoName) => {
    const wasmCanvas = wasmCanvasRef.current
    const Module = moduleRef.current
    if (!wasmCanvas || !Module) return

    try {
      switch (demoName) {
        case 'shapes': {
          wasmCanvas.clear(0.95, 0.95, 0.95, 1.0)

          // Blue rectangle
          wasmCanvas.drawRect(50, 50, 200, 150, 0.4, 0.47, 0.93, 1.0)

          // Red rectangle
          wasmCanvas.drawRect(150, 150, 200, 150, 0.93, 0.3, 0.22, 0.8)

          // Green triangle
          const trianglePoints = new Module.VectorFloat()
          ;[400, 50, 500, 200, 300, 200].forEach(v => trianglePoints.push_back(v))
          wasmCanvas.drawConvexPolygon(trianglePoints, 0.2, 0.8, 0.2, 1.0)
          trianglePoints.delete()

          // Purple hexagon
          const hexPoints = new Module.VectorFloat()
          const centerX = 600, centerY = 350, radius = 80
          for (let i = 0; i < 6; i++) {
            const angle = (i * Math.PI * 2) / 6
            hexPoints.push_back(centerX + radius * Math.cos(angle))
            hexPoints.push_back(centerY + radius * Math.sin(angle))
          }
          wasmCanvas.drawConvexPolygon(hexPoints, 0.58, 0.4, 0.64, 1.0)
          hexPoints.delete()
          break
        }

        case 'transforms': {
          wasmCanvas.clear(1.0, 1.0, 1.0, 1.0)
          const centerX = 400, centerY = 300, rectCount = 6
          const rectWidth = 200, rectHeight = 100

          for (let i = 0; i < rectCount; i++) {
            wasmCanvas.save()
            wasmCanvas.translate(centerX, centerY)
            wasmCanvas.rotate((i * Math.PI * 2) / rectCount)
            wasmCanvas.drawRect(-rectWidth/2, -rectHeight/2, rectWidth, rectHeight,
              0.2 + i * 0.1, 0.5, 0.8, 0.7)
            wasmCanvas.restore()
          }
          break
        }

        case 'gradients':
          wasmCanvas.clear(0.1, 0.1, 0.1, 1.0)

          const colors = new Module.VectorFloat()
          ;[1.0, 0.2, 0.5, 1.0, 0.2, 0.5, 1.0, 1.0, 1.0, 0.9, 0.2, 1.0].forEach(v => colors.push_back(v))

          const shader = Module.createLinearGradient(50, 100, 350, 500, colors, Module.TileMode.Clamp)
          const paint = new Module.PaintWrapper()
          paint.setShader(shader.getPtr())
          wasmCanvas.drawRectWithPaint(50, 100, 300, 400, paint)

          colors.delete()
          paint.delete()
          shader.delete()
          break

        case 'blend-modes':
          wasmCanvas.clear(1.0, 1.0, 1.0, 1.0)

          // Blue circle
          const circle1 = new Module.PathWrapper()
          circle1.addCircle(350, 300, 100, Module.PathDirection.CW)
          const paint1 = new Module.PaintWrapper()
          paint1.setColor(0.2, 0.5, 1.0, 0.7)
          wasmCanvas.drawPathWithPaint(circle1, paint1)
          circle1.delete()
          paint1.delete()

          // Red circle with multiply blend
          const circle2 = new Module.PathWrapper()
          circle2.addCircle(450, 300, 100, Module.PathDirection.CW)
          const paint2 = new Module.PaintWrapper()
          paint2.setColor(1.0, 0.3, 0.3, 0.7)
          paint2.setBlendMode(Module.BlendMode.Multiply)
          wasmCanvas.drawPathWithPaint(circle2, paint2)
          circle2.delete()
          paint2.delete()
          break

        case 'paths':
          wasmCanvas.clear(1.0, 1.0, 1.0, 1.0)

          // Heart shape
          const heart = new Module.PathWrapper()
          const hx = 200, hy = 200, s = 1.0
          heart.moveTo(hx, hy)
          heart.cubicTo(hx, hy - 50*s, hx - 50*s, hy - 80*s, hx - 80*s, hy - 50*s)
          heart.cubicTo(hx - 110*s, hy - 20*s, hx - 110*s, hy + 20*s, hx - 80*s, hy + 50*s)
          heart.lineTo(hx, hy + 120*s)
          heart.lineTo(hx + 80*s, hy + 50*s)
          heart.cubicTo(hx + 110*s, hy + 20*s, hx + 110*s, hy - 20*s, hx + 80*s, hy - 50*s)
          heart.cubicTo(hx + 50*s, hy - 80*s, hx, hy - 50*s, hx, hy)

          const paintHeart = new Module.PaintWrapper()
          paintHeart.setColor(0.93, 0.3, 0.22, 1.0)
          wasmCanvas.drawPathWithPaint(heart, paintHeart)
          heart.delete()
          paintHeart.delete()

          // Star
          const star = new Module.PathWrapper()
          const sx = 550, sy = 250, outerR = 100, innerR = 40
          for (let i = 0; i < 5; i++) {
            const angle = (i * Math.PI * 2) / 5 - Math.PI / 2
            const x = sx + outerR * Math.cos(angle)
            const y = sy + outerR * Math.sin(angle)
            if (i === 0) star.moveTo(x, y)
            else star.lineTo(x, y)

            const innerAngle = angle + Math.PI / 5
            const ix = sx + innerR * Math.cos(innerAngle)
            const iy = sy + innerR * Math.sin(innerAngle)
            star.lineTo(ix, iy)
          }

          const paintStar = new Module.PaintWrapper()
          paintStar.setColor(1.0, 0.84, 0.0, 1.0)
          wasmCanvas.drawPathWithPaint(star, paintStar)
          star.delete()
          paintStar.delete()
          break

        default:
          wasmCanvas.clear(0.95, 0.95, 0.95, 1.0)
          wasmCanvas.drawRect(50, 50, 200, 150, 0.4, 0.47, 0.93, 1.0)
      }

      updateCanvasDisplay()
    } catch (err) {
      console.error('Demo error:', err)
    }
  }

  const handleDemoChange = (e) => {
    const demo = e.target.value
    setCurrentDemo(demo)
    setDemoDescription(demoInfo[demo])
  }

  const handleClear = () => {
    if (wasmCanvasRef.current) {
      wasmCanvasRef.current.clear(1.0, 1.0, 1.0, 1.0)
      updateCanvasDisplay()
    }
  }

  const breadcrumbItems = [
    { label: 'Home', href: '/' },
    { label: 'Graphics Engine', href: '/projects/graphics-engine/wasm' },
    { label: 'Interactive Demo' }
  ]

  return (
    <div>
      <style>{`
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
            background: linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%);
            color: #333;
            min-height: 100vh;
            padding: 2rem;
        }

        .container {
            max-width: 1400px;
            margin: 0 auto;
            background: white;
            border-radius: 12px;
            box-shadow: 0 20px 60px rgba(0,0,0,0.3);
            overflow: hidden;
        }

        header {
            background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
            color: white;
            padding: 2rem;
            text-align: center;
        }

        header h1 {
            margin-bottom: 0.5rem;
            font-size: 2rem;
        }

        header p {
            opacity: 0.9;
            font-size: 1.1rem;
        }

        .badge {
            display: inline-block;
            background: #2E7D32;
            color: white;
            padding: 0.25rem 0.75rem;
            border-radius: 12px;
            font-size: 0.85rem;
            margin-top: 0.5rem;
            font-weight: 600;
        }

        .content {
            display: grid;
            grid-template-columns: 320px 1fr;
            gap: 2rem;
            padding: 2rem;
        }

        .controls {
            background: #f8f9fa;
            padding: 1.5rem;
            border-radius: 8px;
            max-height: calc(100vh - 250px);
            overflow-y: auto;
        }

        .control-group {
            margin-bottom: 1.5rem;
        }

        .control-group label {
            display: block;
            font-weight: 600;
            margin-bottom: 0.5rem;
            color: #2c3e50;
        }

        .control-group select {
            width: 100%;
            padding: 0.5rem;
            border: 1px solid #ddd;
            border-radius: 4px;
            font-size: 1rem;
        }

        button {
            width: 100%;
            padding: 0.75rem;
            background: #2E7D32;
            color: white;
            border: none;
            border-radius: 4px;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            transition: background 0.3s;
            margin-bottom: 0.5rem;
        }

        button:hover:not(:disabled) {
            background: #1B5E20;
        }

        button:focus-visible {
            outline: 2px solid white;
            outline-offset: 2px;
        }

        button:disabled {
            background: #ccc;
            cursor: not-allowed;
        }

        button.secondary {
            background: #e74c3c;
        }

        button.secondary:hover:not(:disabled) {
            background: #c0392b;
        }

        .canvas-container {
            background: #f0f0f0;
            border-radius: 8px;
            padding: 1rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 600px;
        }

        #canvas {
            background: white;
            border: 2px solid #ddd;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
        }

        #status {
            padding: 1rem;
            border-radius: 6px;
            margin-bottom: 1rem;
            text-align: center;
            font-weight: 600;
        }

        #status.loading {
            background: #fff3cd;
            border: 2px solid #ffc107;
            color: #856404;
        }

        #status.success {
            background: #d4edda;
            border: 2px solid #28a745;
            color: #155724;
        }

        #status.error {
            background: #f8d7da;
            border: 2px solid #dc3545;
            color: #721c24;
        }

        .info {
            background: #e8f4f8;
            padding: 1rem;
            border-radius: 4px;
            margin-bottom: 1rem;
            font-size: 0.9rem;
            line-height: 1.6;
        }

        .demo-description {
            background: white;
            padding: 1rem;
            border-radius: 6px;
            border-left: 4px solid #2E7D32;
            margin-bottom: 1rem;
            font-size: 0.9rem;
            line-height: 1.5;
        }

        .demo-description h3 {
            margin-bottom: 0.5rem;
            color: #2E7D32;
        }

        footer {
            background: #2c3e50;
            color: white;
            text-align: center;
            padding: 1rem;
        }

        footer a {
            color: #2E7D32;
            text-decoration: none;
        }

        footer a:hover {
            text-decoration: underline;
        }

        @media (max-width: 900px) {
            .content {
                grid-template-columns: 1fr;
            }

            .controls {
                max-height: none;
                overflow-y: visible;
            }
        }

        .spinner {
            border: 4px solid #f3f3f3;
            border-top: 4px solid #2E7D32;
            border-radius: 50%;
            width: 40px;
            height: 40px;
            animation: spin 1s linear infinite;
            margin: 0 auto 1rem;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
      `}</style>

      <Breadcrumbs items={breadcrumbItems} />

      <div className="container">
        <header>
          <h1>🎨 C++ Graphics Engine</h1>
          <p>Real-time 2D rendering powered by C++ and WebAssembly</p>
          <span className="badge">Phase 4 Complete: Interactive Controls</span>
        </header>

        <div className="content">
          <div className="controls">
            <div className="info">
              <strong>⚡ Real C++ Engine</strong><br />
              This is not a JavaScript simulation - it's my actual C++ graphics engine compiled to WebAssembly and running in your browser at near-native speed!
            </div>

            <div className="demo-description">
              <h3>{demoDescription.title}</h3>
              <p>{demoDescription.description}</p>
            </div>

            <div className="control-group">
              <label>Demo Preset</label>
              <select
                id="demoPreset"
                value={currentDemo}
                onChange={handleDemoChange}
                disabled={controlsDisabled}
              >
                <option value="shapes">Basic Shapes</option>
                <option value="transforms">Transformations</option>
                <option value="gradients">Linear Gradients</option>
                <option value="radial-gradients">Radial Gradients</option>
                <option value="sweep-gradients">Sweep Gradients</option>
                <option value="bitmap-shader">Bitmap Shader</option>
                <option value="blend-modes">Blend Modes</option>
                <option value="paths">Curved Paths</option>
                <option value="mesh">Mesh Rendering</option>
                <option value="poly-spiral">Polygon Spiral</option>
              </select>
            </div>

            <div id="dynamicControls">
              {/* Controls will be generated dynamically here */}
            </div>

            <button
              className="secondary"
              id="clearBtn"
              onClick={handleClear}
              disabled={controlsDisabled}
            >
              Clear Canvas
            </button>
          </div>

          <div className="canvas-container">
            <div id="status" className={status.type}>
              {status.type === 'loading' && <div className="spinner"></div>}
              {status.message}
            </div>
            <canvas
              ref={canvasRef}
              id="canvas"
              width="800"
              height="600"
              style={{ display: 'none' }}
            />
          </div>
        </div>

        <footer>
          <p>Built by Aaron Diefes | <Link to="/">Back to Home</Link> | <Link to="/admin">View Source Code</Link></p>
        </footer>
      </div>
    </div>
  )
}

export default GraphicsWasmPage

