      const dx = ax - cx
      const dy = ay - cy
      const len = Math.sqrt(dx*dx + dy*dy)
      const lineEndX = cx + (dx/len) * radius
      const lineEndY = cy + (dy/len) * radius

      // Draw line showing rotation start point
      const line = new Module.PathWrapper()
      line.moveTo(cx, cy)
