    // Iterate through individual parameters
    for (const [paramName, config] of Object.entries(groupParams)) {
      const fullName = `${demoName}_${groupName}_${paramName}`
      html += generateControlHTML(fullName, config)
    }

    html += `</div>`
  }

  return html
}

