      },
      gradient2: {
        x0: { type: 'range', min: 400, max: 800, default: 500, step: 5, label: 'Start X' },
        y0: { type: 'range', min: 0, max: 600, default: 300, step: 5, label: 'Start Y' },
        x1: { type: 'range', min: 400, max: 800, default: 525, step: 5, label: 'End X' },
