        scale: { type: 'range', min: 0.2, max: 3.0, default: 0.3, step: 0.1, label: 'Scale' },
        tileMode: { type: 'select', options: ['Clamp', 'Repeat', 'Mirror'], default: 'Repeat', label: 'Tile Mode' }
      }
    },

    mesh: {
