      }
    },

    'bitmap-shader': {
      texture1: {
        x: { type: 'range', min: 0, max: 800, default: 50, step: 10, label: 'X Position' },
        y: { type: 'range', min: 0, max: 600, default: 50, step: 10, label: 'Y Position' },
        scale: { type: 'range', min: 0.2, max: 3.0, default: 0.5, step: 0.1, label: 'Scale' },
