        }

        button.secondary {
            background: #e74c3c;
        }

        button.secondary:hover:not(:disabled) {
            background: #c0392b;
        }

        .canvas-container {
            background: #f0f0f0;
            border-radius: 8px;
            padding: 1rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 600px;
        }

        #canvas {
            background: white;
            border: 2px solid #ddd;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
        }

        #status {
            padding: 1rem;
            border-radius: 6px;
            margin-bottom: 1rem;
            text-align: center;
