            background: #e8f4f8;
            padding: 1rem;
            border-radius: 4px;
            margin-bottom: 1rem;
            font-size: 0.9rem;
            line-height: 1.6;
        }

        .demo-description {
            background: white;
            padding: 1rem;
            border-radius: 6px;
            border-left: 4px solid #2E7D32;
            margin-bottom: 1rem;
            font-size: 0.9rem;
            line-height: 1.5;
        }

        .demo-description h3 {
            margin-bottom: 0.5rem;
            color: #2E7D32;
        }

