        }

        button:hover:not(:disabled) {
            background: #1B5E20;
        }

        button:focus-visible {
            outline: 2px solid white;
            outline-offset: 2px;
        }

        button:disabled {
            background: #ccc;
            cursor: not-allowed;
        }

        button.secondary {
            background: #e74c3c;
        }

        button.secondary:hover:not(:disabled) {
            background: #c0392b;
        }

        .canvas-container {
            background: #f0f0f0;
            border-radius: 8px;
