            <canvas
              ref={canvasRef}
              id="canvas"
              width="800"
              height="600"
              style={{ display: 'none' }}
            />
          </div>
        </div>

        <footer>
          <p>Built by Aaron Diefes | <Link to="/">Back to Home</Link> | <Link to="/admin">View Source Code</Link></p>
        </footer>
      </div>
    </div>
  )
}

